import assert from 'node:assert';
import { test } from 'node:test';
import { createState, collides, frame, UP, DOWN, LEFT, RIGHT, WIDTH, HEIGHT } from '../game/neon.js';

// Mock canvas context
const ctx = {
  fillRect: () => {},
  fillText: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
};

test('Symptôme: Balle traverse la brique (pas de rebond)', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // Top-left brick

  // Position the ball just above the brick, moving DOWN
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 1;
  state.ball.vy = 100; 
  state.ball.vx = 0;

  // Simulate one frame where collision happens
  // In the real game, step() moves the ball, then frame() checks collision.
  // Here we force the collision.
  state.ball.y += 2; // Now it overlaps

  const vyBefore = state.ball.vy;
  frame(ctx, state);

  assert.strictEqual(state.ball.vy, -vyBefore, 'La vitesse vy doit être inversée lors d\'un impact sur la face haute');
});

test('Défaut: Collant (Sticking) - Simulation d\'une correction naïve', () => {
  // This test simulates what happens if we only flip velocity without repositioning.
  const state = createState(1);
  const brick = state.bricks[0];

  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + 2; // Already inside
  state.ball.vy = 100;

  // First frame: collision detected -> flip vy to -100
  if (collides(state.ball, brick)) {
    state.ball.vy *= -1;
  }

  // Second frame: ball is still inside -> flip vy back to 100
  if (collides(state.ball, brick)) {
    state.ball.vy *= -1;
  }

  assert.notStrictEqual(state.ball.vy, 100, 'La balle ne doit pas rester collée/vibrer dans la brique');
});

test('Défaut: Double inversion (Ghost collision)', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[1]; // brick to the right

  // Position ball so it overlaps both bricks (on the seam)
  state.ball.x = brick1.x + brick1.w; 
  state.ball.y = brick1.y + brick1.h / 2;
  state.ball.vx = 100;
  state.ball.vy = 0;

  // Simulate frame: loop through bricks
  // If naive implementation flips vx for each collision:
  let vx = state.ball.vx;
  if (collides(state.ball, brick1)) vx *= -1;
  if (collides(state.ball, brick2)) vx *= -1;

  assert.notStrictEqual(vx, 100, 'La balle ne doit pas traverser la couture entre deux briques');
});

test('Défaut: Traversée (Tunneling) - High speed', () => {
  const state = createState(10); // Level 10 = very fast
  const speed = 260 + 9 * 90; // 1070 px/s
  const dt = 0.05;
  const stepDist = speed * dt; // 53.5 px

  const brick = state.bricks[0];
  const thickness = brick.h + state.ball.r * 2; // 20 + 14 = 34 px

  assert.ok(stepDist > thickness, 'À haut niveau, le pas de temps permet de franchir la brique');

  // Simulation of a tunneling frame
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 5; // Just above
  state.ball.vy = speed;

  // Move the ball
  state.ball.y += speed * dt; // y = brick.y - 5 + 53.5 = brick.y + 48.5

  // Ball is now BELOW the brick (brick.y + brick.h = brick.y + 20)
  assert.strictFalse(collides(state.ball, brick), 'La balle a tunnelisé à travers la brique');
});

import assert from 'node:assert';
import { test } from 'node:test';
import { createState, collides, frame, UP, DOWN, LEFT, RIGHT, WIDTH, HEIGHT } from '../game/neon.js';

const ctx = {
  fillRect: () => {},
  fillText: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
};

test('D1: Symptôme - Pas de rebond', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 1;
  state.ball.vy = 100; 
  state.ball.vx = 0;
  state.ball.y += 2; 
  const vyBefore = state.ball.vy;
  frame(ctx, state);
  assert.strictEqual(state.ball.vy, -vyBefore, 'La vitesse vy doit être inversée');
});

test('D2: Collant (Sticking)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + 2; // Inside
  state.ball.vy = 100;

  // Simulate naive correction: flip velocity if colliding
  const simulateNaive = (s, b) => {
    if (collides(s.ball, b)) {
      s.ball.vy *= -1;
    }
  };

  simulateNaive(state, brick); // vy = -100
  simulateNaive(state, brick); // vy = 100
  assert.notStrictEqual(state.ball.vy, 100, 'La balle ne doit pas rester collée');
});

test('D3: Double inversion (Ghost collision)', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[1];
  state.ball.x = brick1.x + brick1.w + 4; // Centered in gap
  state.ball.y = brick1.y + brick1.h / 2;
  state.ball.vx = 100;
  state.ball.vy = 0;

  let vx = state.ball.vx;
  if (collides(state.ball, brick1)) vx *= -1;
  if (collides(state.ball, brick2)) vx *= -1;

  assert.notStrictEqual(vx, 100, 'La balle ne doit pas traverser la couture');
});

test('D4: Traversée (Tunneling)', () => {
  const state = createState(10);
  const speed = 260 + 9 * 90; 
  const dt = 0.05;
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 5;
  state.ball.vy = speed;
  state.ball.y += speed * dt; 
  assert.strictEqual(collides(state.ball, brick), false, 'La balle a tunnelisé');
});

