test('frame: no ghost collision at seams (D3)', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[1];
  state.ball.x = brick1.x + brick1.w + 4; // Centered in gap
  state.ball.y = brick1.y + brick1.h / 2;
  state.ball.vx = 100;
  state.ball.vy = 0;

  frame(ctx, state);

  assert.strictEqual(state.ball.vx, -100, 'La vitesse vx doit être inversée une seule fois');
});

test('physics: no tunneling at high speed (D4)', () => {
  const state = createState(10);
  const speed = 260 + 9 * 90; 
  const dt = 0.05;
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 5;
  state.ball.vy = speed;

  // This is how the game loop currently works:
  // 1. step()
  // 2. frame() (which handles collisions)

  // We simulate the move
  step(state, dt); 
  frame(ctx, state);

  assert.ok(!brick.alive, 'La brique doit être détruite même à haute vitesse');
  assert.ok(state.ball.vy < 0, 'La balle doit avoir rebondi');
});

