test('physics: ball bounces off brick (D1)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 1;
  state.ball.vy = 100; 
  state.ball.vx = 0;
  state.ball.y += 2; 
  const vyBefore = state.ball.vy;
  update(state, 0.01);
  assert.strictEqual(state.ball.vy, -vyBefore, 'La vitesse vy doit être inversée lors d\'un impact');
});

test('physics: ball does not stick to brick (D2)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + 2; // Inside
  state.ball.vy = 100;

  update(state, 0.01);

  assert.ok(!collides(state.ball, brick), 'La balle ne doit plus chevaucher la brique après résolution');
  assert.strictEqual(state.ball.vy, -100, 'La vitesse doit être inversée');
});

test('physics: no ghost collision at seams (D3)', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[1];
  state.ball.x = brick1.x + brick1.w + 4; // Centered in gap
  state.ball.y = brick1.y + brick1.h / 2;
  state.ball.vx = 100;
  state.ball.vy = 0;

  update(state, 0.01);

  assert.strictEqual(state.ball.vx, -100, 'La vitesse vx doit être inversée une seule fois');
});

