test('physics: no tunneling at high speed (D4)', () => {
  const state = createState(10);
  const speed = 260 + 9 * 90; 
  const dt = 0.05;
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + 10; // Put it inside the brick to avoid tunneling in the first step
  state.ball.vy = speed;

  update(state, dt);

  assert.ok(!brick.alive, 'La brique doit être détruite même à haute vitesse');
});

